/**
 * Admin i18n. The admin UI follows the store's default language, with a manual
 * override in Settings (persisted to localStorage). Ships curated EN + EU
 * majors; any locale not present (or any untranslated key) falls back to
 * English, so the app is always usable for anyone who installs it.
 *
 * Coverage is migrated key-by-key: wrap an admin string in `t("some.key")` and
 * add the key to EN (+ the other languages when available).
 */

import {
  createContext,
  useContext,
  useEffect,
  useMemo,
  useState,
  type ReactNode,
} from "react";

export type Locale = "en" | "es" | "fr" | "de" | "it" | "pt" | "nl" | "pl";

export const LOCALES: Locale[] = ["en", "es", "fr", "de", "it", "pt", "nl", "pl"];

export const LOCALE_NAMES: Record<Locale, string> = {
  en: "English",
  es: "Español",
  fr: "Français",
  de: "Deutsch",
  it: "Italiano",
  pt: "Português",
  nl: "Nederlands",
  pl: "Polski",
};

// Fallback when the store's primary locale is unknown (the real default is
// detected from `shop.primaryLocale` in the app loader and passed to
// LocaleProvider via `defaultLocale`).
export const STORE_DEFAULT_LOCALE: Locale = "en";

/**
 * Map a Shopify locale (e.g. "de", "de-DE", "pt-BR") to one of our supported
 * admin locales by 2-letter prefix; anything unknown falls back to English.
 */
export function toSupportedLocale(raw: string | null | undefined): Locale {
  const prefix = (raw ?? "").toLowerCase().slice(0, 2);
  return (LOCALES as string[]).includes(prefix) ? (prefix as Locale) : "en";
}

