  "Progress bar + text": { es: "Barra de progreso + texto", fr: "Barre de progression + texte", de: "Fortschrittsbalken + Text", it: "Barra di avanzamento + testo", pt: "Barra de progresso + texto", nl: "Voortgangsbalk + tekst", pl: "Pasek postępu + tekst" },
