  "Urgency pill": { es: "Píldora de urgencia", fr: "Pastille d'urgence", de: "Dringlichkeits-Badge", it: "Etichetta di urgenza", pt: "Selo de urgência", nl: "Urgentie-label", pl: "Plakietka pilności" },
