  "Deposit": { es: "Depósito", fr: "Acompte", de: "Anzahlung", it: "Acconto", pt: "Depósito", nl: "Aanbetaling", pl: "Zaliczka" },
  "Deposit now, balance before shipping": { es: "Depósito ahora, saldo antes del envío", fr: "Acompte maintenant, solde avant l'expédition", de: "Anzahlung jetzt, Rest vor dem Versand", it: "Acconto ora, saldo prima della spedizione", pt: "Depósito agora, saldo antes do envio", nl: "Nu aanbetaling, rest vóór verzending", pl: "Zaliczka teraz, reszta przed wysyłką" },
  "Details": { es: "Detalles", fr: "Détails", de: "Details", it: "Dettagli", pt: "Detalhes", nl: "Details", pl: "Szczegóły" },
  "Discount, button text, delivery note, cohort name, internal notes.": { es: "Descuento, texto del botón, nota de entrega, nombre del lote, notas internas.", fr: "Remise, texte du bouton, note de livraison, nom de cohorte, notes internes.", de: "Rabatt, Button-Text, Liefernotiz, Kohortenname, interne Notizen.", it: "Sconto, testo del pulsante, nota di consegna, nome coorte, note interne.", pt: "Desconto, texto do botão, nota de entrega, nome do lote, notas internas.", nl: "Korting, knoptekst, leveringsnotitie, cohortnaam, interne notities.", pl: "Rabat, tekst przycisku, notatka dostawy, nazwa kohorty, notatki wewnętrzne." },
  "Every product in one collection.": { es: "Todos los productos de una colección.", fr: "Tous les produits d'une collection.", de: "Alle Produkte einer Kollektion.", it: "Tutti i prodotti di una collezione.", pt: "Todos os produtos de uma coleção.", nl: "Alle producten in één collectie.", pl: "Wszystkie produkty z jednej kolekcji." },
  "Fix": { es: "Corregir", fr: "Corriger", de: "Beheben", it: "Correggi", pt: "Corrigir", nl: "Oplossen", pl: "Napraw" },
