  "Full payment at checkout": { es: "Pago completo al pagar", fr: "Paiement total à la commande", de: "Vollständige Zahlung beim Checkout", it: "Pagamento completo al checkout", pt: "Pagamento total no checkout", nl: "Volledige betaling bij afrekenen", pl: "Pełna płatność przy kasie" },
  "How customers pay for this preorder. The store default comes from Settings.": { es: "Cómo pagan los clientes esta preventa. El valor predeterminado viene de Ajustes.", fr: "Comment les clients paient cette précommande. La valeur par défaut vient des Paramètres.", de: "Wie Kunden diesen Vorverkauf bezahlen. Der Shop-Standard kommt aus den Einstellungen.", it: "Come i clienti pagano questo preordine. Il valore predefinito viene dalle Impostazioni.", pt: "Como os clientes pagam esta pré-venda. O padrão da loja vem das Definições.", nl: "Hoe klanten deze pre-order betalen. De standaard komt uit Instellingen.", pl: "Jak klienci płacą za tę przedsprzedaż. Domyślne ustawienie pochodzi z Ustawień." },
  "More options": { es: "Más opciones", fr: "Plus d'options", de: "Weitere Optionen", it: "Altre opzioni", pt: "Mais opções", nl: "Meer opties", pl: "Więcej opcji" },
  "None": { es: "Ninguno", fr: "Aucune", de: "Keine", it: "Nessuno", pt: "Nenhum", nl: "Geen", pl: "Brak" },
