  "Not set": { es: "Sin definir", fr: "Non défini", de: "Nicht festgelegt", it: "Non impostato", pt: "Não definido", nl: "Niet ingesteld", pl: "Nie ustawiono" },
  "Only the products and variants you pick.": { es: "Solo los productos y variantes que elijas.", fr: "Uniquement les produits et variantes choisis.", de: "Nur die ausgewählten Produkte und Varianten.", it: "Solo i prodotti e le varianti che scegli.", pt: "Apenas os produtos e variantes que escolher.", nl: "Alleen de producten en varianten die je kiest.", pl: "Tylko wybrane produkty i warianty." },
  "Only your team sees this.": { es: "Solo lo ve tu equipo.", fr: "Visible uniquement par votre équipe.", de: "Nur dein Team sieht das.", it: "Lo vede solo il tuo team.", pt: "Apenas a sua equipa vê isto.", nl: "Alleen je team ziet dit.", pl: "Widzi to tylko Twój zespół." },
  "Pay later (on ship)": { es: "Pagar después (al enviar)", fr: "Payer plus tard (à l'expédition)", de: "Später zahlen (bei Versand)", it: "Paga dopo (alla spedizione)", pt: "Pagar depois (no envio)", nl: "Later betalen (bij verzending)", pl: "Zapłać później (przy wysyłce)" },
  "Pay later — charged when it ships": { es: "Pagar después: se cobra al enviar", fr: "Payer plus tard — débité à l'expédition", de: "Später zahlen – Abbuchung bei Versand", it: "Paga dopo — addebito alla spedizione", pt: "Pagar depois — cobrado no envio", nl: "Later betalen — afgeschreven bij verzending", pl: "Zapłać później — pobranie przy wysyłce" },
  "Pick whole products or single variants from your catalog.": { es: "Elige productos completos o variantes sueltas de tu catálogo.", fr: "Choisissez des produits entiers ou des variantes de votre catalogue.", de: "Wähle ganze Produkte oder einzelne Varianten aus deinem Katalog.", it: "Scegli prodotti interi o singole varianti dal catalogo.", pt: "Escolha produtos inteiros ou variantes do seu catálogo.", nl: "Kies hele producten of losse varianten uit je catalogus.", pl: "Wybierz całe produkty lub pojedyncze warianty z katalogu." },
  "Products": { es: "Productos", fr: "Produits", de: "Produkte", it: "Prodotti", pt: "Produtos", nl: "Producten", pl: "Produkty" },
  "Ready to publish": { es: "Listo para publicar", fr: "Prêt à publier", de: "Bereit zur Veröffentlichung", it: "Pronto per la pubblicazione", pt: "Pronto para publicar", nl: "Klaar om te publiceren", pl: "Gotowe do publikacji" },
  "Shown to customers on the product page and in emails.": { es: "Se muestra a los clientes en la página del producto y en los correos.", fr: "Affichée aux clients sur la page produit et dans les e-mails.", de: "Wird Kunden auf der Produktseite und in E-Mails angezeigt.", it: "Mostrata ai clienti nella pagina prodotto e nelle email.", pt: "Mostrada aos clientes na página do produto e nos e-mails.", nl: "Getoond aan klanten op de productpagina en in e-mails.", pl: "Widoczna dla klientów na stronie produktu i w e-mailach." },
  "Stop taking preorders once this many have sold. Leave empty for no cap.": { es: "Deja de aceptar preventas al vender esta cantidad. Vacío = sin límite.", fr: "Arrête les précommandes une fois cette quantité vendue. Vide = sans limite.", de: "Vorverkauf stoppt, sobald so viele verkauft sind. Leer = kein Limit.", it: "Interrompe i preordini una volta venduta questa quantità. Vuoto = nessun limite.", pt: "Deixa de aceitar pré-vendas ao vender esta quantidade. Vazio = sem limite.", nl: "Stop met pre-orders zodra dit aantal verkocht is. Leeg = geen limiet.", pl: "Zatrzymaj przedsprzedaż po sprzedaniu tej liczby. Puste = bez limitu." },
  "Store health": { es: "Estado de la tienda", fr: "Santé de la boutique", de: "Shop-Zustand", it: "Stato del negozio", pt: "Estado da loja", nl: "Winkelstatus", pl: "Kondycja sklepu" },
  "Take a deposit at checkout; the rest is charged automatically before the ship date.": { es: "Cobra un depósito al pagar; el resto se cobra automáticamente antes del envío.", fr: "Prenez un acompte au paiement ; le solde est débité automatiquement avant l'expédition.", de: "Anzahlung beim Checkout; der Rest wird vor dem Versanddatum automatisch abgebucht.", it: "Acconto al checkout; il resto viene addebitato automaticamente prima della spedizione.", pt: "Depósito no checkout; o resto é cobrado automaticamente antes do envio.", nl: "Aanbetaling bij afrekenen; de rest wordt vóór de verzenddatum automatisch afgeschreven.", pl: "Zaliczka przy kasie; reszta pobierana automatycznie przed wysyłką." },
  "Units offered": { es: "Unidades ofrecidas", fr: "Unités proposées", de: "Angebotene Einheiten", it: "Unità offerte", pt: "Unidades oferecidas", nl: "Aangeboden eenheden", pl: "Oferowane sztuki" },
  "Waitlist delivery": { es: "Entrega de lista de espera", fr: "Envoi liste d'attente", de: "Wartelisten-Zustellung", it: "Consegna lista d'attesa", pt: "Entrega da lista de espera", nl: "Levering wachtlijst", pl: "Dostarczanie listy oczekujących" },
  "What customers can preorder.": { es: "Lo que los clientes pueden reservar.", fr: "Ce que les clients peuvent précommander.", de: "Was Kunden vorbestellen können.", it: "Cosa possono preordinare i clienti.", pt: "O que os clientes podem pré-encomendar.", nl: "Wat klanten kunnen pre-orderen.", pl: "Co klienci mogą zamówić w przedsprzedaży." },
  "Your most recent preorders.": { es: "Tus preventas más recientes.", fr: "Vos précommandes les plus récentes.", de: "Deine neuesten Vorverkäufe.", it: "I tuoi preordini più recenti.", pt: "As suas pré-vendas mais recentes.", nl: "Je meest recente pre-orders.", pl: "Twoje najnowsze przedsprzedaże." },
  "Your whole catalog, governed by the inventory rules in Settings.": { es: "Todo tu catálogo, según las reglas de inventario de Ajustes.", fr: "Tout votre catalogue, selon les règles de stock des Paramètres.", de: "Dein gesamter Katalog, gesteuert durch die Bestandsregeln in den Einstellungen.", it: "Tutto il catalogo, secondo le regole di inventario nelle Impostazioni.", pt: "Todo o seu catálogo, segundo as regras de inventário nas Definições.", nl: "Je hele catalogus, volgens de voorraadregels in Instellingen.", pl: "Cały katalog, zgodnie z regułami magazynowymi w Ustawieniach." },
