  "Customers are tagged in Shopify and Encore sends the restock email for you.": { es: "Los clientes se etiquetan en Shopify y Encore envía el correo de reposición.", fr: "Les clients sont tagués dans Shopify et Encore envoie l'e-mail pour vous.", de: "Kunden werden in Shopify getaggt und Encore sendet die E-Mail für dich.", it: "I clienti vengono taggati in Shopify ed Encore invia l'email per te.", pt: "Os clientes são etiquetados no Shopify e o Encore envia o e-mail por si.", nl: "Klanten krijgen een tag in Shopify en Encore verstuurt de e-mail voor je.", pl: "Klienci są tagowani w Shopify, a Encore wysyła e-mail za Ciebie." },
  "Double opt-in": { es: "Doble confirmación", fr: "Double opt-in", de: "Double-Opt-in", it: "Doppio opt-in", pt: "Dupla confirmação", nl: "Dubbele opt-in", pl: "Podwójna zgoda" },
  "Email": { es: "Correo", fr: "E-mail", de: "E-Mail", it: "Email", pt: "E-mail", nl: "E-mail", pl: "E-mail" },
  "Encore only": { es: "Solo Encore", fr: "Encore uniquement", de: "Nur Encore", it: "Solo Encore", pt: "Apenas Encore", nl: "Alleen Encore", pl: "Tylko Encore" },
  "Exclude products by tag or collection.": { es: "Excluye productos por etiqueta o colección.", fr: "Excluez des produits par tag ou collection.", de: "Produkte nach Tag oder Kollektion ausschließen.", it: "Escludi prodotti per tag o collezione.", pt: "Exclua produtos por etiqueta ou coleção.", nl: "Sluit producten uit op tag of collectie.", pl: "Wyklucz produkty według tagu lub kolekcji." },
