  "Waitlist conversion, lift and captured revenue": { es: "Conversión de lista de espera, incremento e ingresos captados", fr: "Conversion de la liste d'attente, gain et revenus captés", de: "Warteliste-Conversion, Uplift und erfasster Umsatz", it: "Conversione lista d'attesa, incremento e ricavi acquisiti", pt: "Conversão da lista de espera, ganho e receita captada", nl: "Wachtlijstconversie, lift en gerealiseerde omzet", pl: "Konwersja listy oczekujących, wzrost i pozyskany przychód" },
