  "Expected columns: email, product_id or product_handle, and optionally variant_id, locale.": { es: "Columnas esperadas: email, product_id o product_handle y, opcionalmente, variant_id, locale.", fr: "Colonnes attendues : email, product_id ou product_handle et, en option, variant_id, locale.", de: "Erwartete Spalten: email, product_id oder product_handle sowie optional variant_id, locale.", it: "Colonne previste: email, product_id o product_handle e, facoltativamente, variant_id, locale.", pt: "Colunas esperadas: email, product_id ou product_handle e, opcionalmente, variant_id, locale.", nl: "Verwachte kolommen: email, product_id of product_handle en optioneel variant_id, locale.", pl: "Oczekiwane kolumny: email, product_id lub product_handle oraz opcjonalnie variant_id, locale." },
