  "Push preorder events into Omnisend automation flows.": { es: "Envía eventos de prepedido a los flujos de automatización de Omnisend.", fr: "Envoyez les événements de précommande dans les flux d'automatisation Omnisend.", de: "Senden Sie Vorbestell-Ereignisse in die Omnisend-Automatisierungsflows.", it: "Invia gli eventi di preordine nei flussi di automazione Omnisend.", pt: "Envie eventos de pré-venda para os fluxos de automação Omnisend.", nl: "Stuur preordergebeurtenissen naar Omnisend-automatiseringsflows.", pl: "Wysyłaj zdarzenia przedsprzedaży do automatyzacji Omnisend." },
  "Enable SMS for back-in-stock alerts": { es: "Activar SMS para alertas de reposición", fr: "Activer les SMS pour les alertes de réassort", de: "SMS für Wieder-verfügbar-Benachrichtigungen aktivieren", it: "Abilita SMS per gli avvisi di riassortimento", pt: "Ativar SMS para alertas de reposição", nl: "Sms inschakelen voor terug-op-voorraadmeldingen", pl: "Włącz SMS dla alertów o dostępności" },
  "Requires Twilio (or compatible) credentials in v1.1.": { es: "Requiere credenciales de Twilio (o compatible) en la v1.1.", fr: "Nécessite des identifiants Twilio (ou compatible) en v1.1.", de: "Erfordert Twilio- (oder kompatible) Zugangsdaten in v1.1.", it: "Richiede credenziali Twilio (o compatibili) nella v1.1.", pt: "Requer credenciais Twilio (ou compatível) na v1.1.", nl: "Vereist Twilio- (of compatibele) gegevens in v1.1.", pl: "Wymaga danych Twilio (lub zgodnych) w v1.1." },
  "Sender email": { es: "Correo del remitente", fr: "E-mail de l'expéditeur", de: "Absender-E-Mail", it: "Email del mittente", pt: "E-mail do remetente", nl: "Afzender-e-mail", pl: "E-mail nadawcy" },
  "Verify SPF/DKIM in your email host before going live.": { es: "Verifica SPF/DKIM en tu proveedor de correo antes de salir en producción.", fr: "Vérifiez SPF/DKIM chez votre hébergeur e-mail avant la mise en production.", de: "Prüfen Sie SPF/DKIM bei Ihrem E-Mail-Host, bevor Sie live gehen.", it: "Verifica SPF/DKIM nel tuo host email prima di andare in produzione.", pt: "Verifique SPF/DKIM no seu fornecedor de e-mail antes de entrar em produção.", nl: "Controleer SPF/DKIM bij je e-mailhost voordat je live gaat.", pl: "Sprawdź SPF/DKIM u dostawcy poczty przed uruchomieniem." },
  "Per-preorder merchant alerts (balance failures, cohort ready).": { es: "Alertas para el comerciante por prepedido (fallos de saldo, cohorte lista).", fr: "Alertes marchand par précommande (échecs de solde, cohorte prête).", de: "Händler-Benachrichtigungen pro Vorbestellung (Saldo-Fehler, Kohorte bereit).", it: "Avvisi al merchant per preordine (saldi non riusciti, coorte pronta).", pt: "Alertas ao comerciante por pré-venda (falhas de saldo, coorte pronta).", nl: "Verkopermeldingen per preorder (saldofouten, cohort gereed).", pl: "Alerty dla sprzedawcy na przedsprzedaż (błędy płatności, gotowa kohorta)." },
  "Advanced": { es: "Avanzado", fr: "Avancé", de: "Erweitert", it: "Avanzate", pt: "Avançado", nl: "Geavanceerd", pl: "Zaawansowane" },
  "Advanced — applied to the storefront block for this store.": { es: "Avanzado: se aplica al bloque de tienda de esta tienda.", fr: "Avancé — appliqué au bloc de boutique de ce magasin.", de: "Erweitert – wird auf den Storefront-Block dieses Shops angewendet.", it: "Avanzate — applicato al blocco vetrina di questo negozio.", pt: "Avançado — aplicado ao bloco da loja desta loja.", nl: "Geavanceerd — toegepast op het storefrontblok van deze winkel.", pl: "Zaawansowane — stosowane do bloku sklepu tego sklepu." },
  "Webhook URL": { es: "URL del webhook", fr: "URL du webhook", de: "Webhook-URL", it: "URL del webhook", pt: "URL do webhook", nl: "Webhook-URL", pl: "URL webhooka" },
