  "Wipe demo data": { es: "Borrar datos de demostración", fr: "Effacer les données de démo", de: "Demodaten löschen", it: "Cancella i dati demo", pt: "Apagar dados de demonstração", nl: "Demogegevens wissen", pl: "Wyczyść dane demonstracyjne" },
