  "Ops handoff, forecasting context, etc.": { es: "Traspaso a operaciones, contexto de previsión, etc.", fr: "Transfert aux opérations, contexte de prévision, etc.", de: "Übergabe an Ops, Forecasting-Kontext usw.", it: "Passaggio alle operations, contesto di previsione, ecc.", pt: "Transferência para operações, contexto de previsão, etc.", nl: "Overdracht aan ops, forecastcontext, enz.", pl: "Przekazanie do operacji, kontekst prognozy itp." },
  "Optional, per this drop. Store-wide options live in Settings.": { es: "Opcional, para este lanzamiento. Las opciones de toda la tienda están en Ajustes.", fr: "Facultatif, pour ce drop. Les options à l'échelle de la boutique sont dans Paramètres.", de: "Optional, für diesen Drop. Shop-weite Optionen finden Sie in den Einstellungen.", it: "Facoltativo, per questo drop. Le opzioni per tutto il negozio sono in Impostazioni.", pt: "Opcional, para este lançamento. As opções de toda a loja estão em Definições.", nl: "Optioneel, voor deze drop. Winkelbrede opties staan in Instellingen.", pl: "Opcjonalne, dla tego dropu. Opcje dla całego sklepu są w Ustawieniach." },
  "Percentage": { es: "Porcentaje", fr: "Pourcentage", de: "Prozentsatz", it: "Percentuale", pt: "Percentagem", nl: "Percentage", pl: "Procent" },
