  "Ship date set": { es: "Fecha de envío definida", fr: "Date d'expédition définie", de: "Versanddatum festgelegt", it: "Data di spedizione impostata", pt: "Data de envio definida", nl: "Verzenddatum ingesteld", pl: "Data wysyłki ustawiona" },
