  "Klaviyo connected.": { es: "Klaviyo conectado.", fr: "Klaviyo connecté.", de: "Klaviyo verbunden.", it: "Klaviyo collegato.", pt: "Klaviyo ligado.", nl: "Klaviyo gekoppeld.", pl: "Połączono Klaviyo." },
  "Klaviyo connection failed. Please try again.": { es: "Falló la conexión con Klaviyo. Inténtalo de nuevo.", fr: "Échec de la connexion Klaviyo. Veuillez réessayer.", de: "Klaviyo-Verbindung fehlgeschlagen. Bitte erneut versuchen.", it: "Connessione a Klaviyo non riuscita. Riprova.", pt: "A ligação ao Klaviyo falhou. Tente novamente.", nl: "Klaviyo-koppeling mislukt. Probeer het opnieuw.", pl: "Połączenie z Klaviyo nie powiodło się. Spróbuj ponownie." },
  "Klaviyo OAuth isn't configured on this app yet — paste an API key instead.": { es: "OAuth de Klaviyo aún no está configurado en esta app: pega una clave API en su lugar.", fr: "OAuth Klaviyo n'est pas encore configuré sur cette app — collez plutôt une clé API.", de: "Klaviyo-OAuth ist für diese App noch nicht konfiguriert – fügen Sie stattdessen einen API-Schlüssel ein.", it: "OAuth di Klaviyo non è ancora configurato su questa app: incolla invece una chiave API.", pt: "O OAuth do Klaviyo ainda não está configurado nesta app — cole antes uma chave API.", nl: "Klaviyo OAuth is nog niet geconfigureerd voor deze app — plak in plaats daarvan een API-sleutel.", pl: "OAuth Klaviyo nie jest jeszcze skonfigurowany w tej aplikacji — wklej zamiast tego klucz API." },
  "Or paste a Klaviyo private API key in Settings → Email integrations.": { es: "O pega una clave API privada de Klaviyo en Ajustes → Integraciones de correo.", fr: "Ou collez une clé API privée Klaviyo dans Paramètres → Intégrations e-mail.", de: "Oder fügen Sie einen privaten Klaviyo-API-Schlüssel unter Einstellungen → E-Mail-Integrationen ein.", it: "Oppure incolla una chiave API privata di Klaviyo in Impostazioni → Integrazioni email.", pt: "Ou cole uma chave API privada do Klaviyo em Definições → Integrações de e-mail.", nl: "Of plak een privé-API-sleutel van Klaviyo in Instellingen → E-mailintegraties.", pl: "Lub wklej prywatny klucz API Klaviyo w Ustawienia → Integracje e-mail." },
  "Connected (OAuth)": { es: "Conectado (OAuth)", fr: "Connecté (OAuth)", de: "Verbunden (OAuth)", it: "Collegato (OAuth)", pt: "Ligado (OAuth)", nl: "Gekoppeld (OAuth)", pl: "Połączono (OAuth)" },
