  "Encore events": { es: "Eventos de Encore", fr: "Événements Encore", de: "Encore-Ereignisse", it: "Eventi Encore", pt: "Eventos Encore", nl: "Encore-gebeurtenissen", pl: "Zdarzenia Encore" },
  "Encore sends events + copy; your Klaviyo flow emails.": { es: "Encore envía eventos y textos; tu flujo de Klaviyo envía los correos.", fr: "Encore envoie les événements et les textes ; votre flux Klaviyo envoie les e-mails.", de: "Encore sendet Ereignisse + Texte; Ihr Klaviyo-Flow versendet die E-Mails.", it: "Encore invia eventi e testi; il tuo flow Klaviyo invia le email.", pt: "O Encore envia eventos e textos; o seu fluxo Klaviyo envia os e-mails.", nl: "Encore stuurt gebeurtenissen + tekst; je Klaviyo-flow verstuurt de e-mails.", pl: "Encore wysyła zdarzenia i treści; e-maile wysyła Twój przepływ Klaviyo." },
  "Encore sends a Back in Stock event on restock.": { es: "Encore envía un evento Back in Stock al reponer.", fr: "Encore envoie un événement Back in Stock au réassort.", de: "Encore sendet bei Wiederauffüllung ein Back-in-Stock-Ereignis.", it: "Encore invia un evento Back in Stock al riassortimento.", pt: "O Encore envia um evento Back in Stock na reposição.", nl: "Encore stuurt een Back in Stock-gebeurtenis bij aanvulling.", pl: "Encore wysyła zdarzenie Back in Stock przy uzupełnieniu zapasu." },
  "A Flow workflow emails via the Encore 'Send email' action.": { es: "Un flujo de trabajo de Flow envía correos mediante la acción 'Send email' de Encore.", fr: "Un workflow Flow envoie les e-mails via l'action « Send email » d'Encore.", de: "Ein Flow-Workflow versendet E-Mails über die Encore-Aktion 'Send email'.", it: "Un workflow Flow invia le email tramite l'azione 'Send email' di Encore.", pt: "Um fluxo do Flow envia e-mails através da ação 'Send email' do Encore.", nl: "Een Flow-workflow e-mailt via de Encore-actie 'Send email'.", pl: "Przepływ Flow wysyła e-maile przez akcję 'Send email' aplikacji Encore." },
  "Back-in-stock mode": { es: "Modo de reposición", fr: "Mode retour en stock", de: "Wieder-verfügbar-Modus", it: "Modalità di riassortimento", pt: "Modo de reposição", nl: "Terug-op-voorraadmodus", pl: "Tryb dostępności" },
  "Subscribe shoppers to Klaviyo's own back-in-stock at signup (needs the catalog synced).": { es: "Suscribe a los clientes al back-in-stock propio de Klaviyo al registrarse (requiere el catálogo sincronizado).", fr: "Abonnez les clients au back-in-stock natif de Klaviyo à l'inscription (nécessite le catalogue synchronisé).", de: "Kunden bei der Anmeldung für Klaviyos eigenes Back-in-Stock anmelden (Katalog muss synchronisiert sein).", it: "Iscrivi i clienti al back-in-stock nativo di Klaviyo alla registrazione (richiede il catalogo sincronizzato).", pt: "Subscreva os clientes no back-in-stock nativo do Klaviyo ao registarem-se (requer o catálogo sincronizado).", nl: "Meld klanten bij aanmelding aan voor Klaviyo's eigen back-in-stock (catalogus moet gesynchroniseerd zijn).", pl: "Zapisuj klientów do natywnego back-in-stock Klaviyo przy rejestracji (wymaga zsynchronizowanego katalogu)." },
  "Most stores already run one of these — no new cost.": { es: "La mayoría de las tiendas ya usan uno de estos: sin coste nuevo.", fr: "La plupart des boutiques utilisent déjà l'un d'eux — aucun coût supplémentaire.", de: "Die meisten Shops nutzen bereits eines davon – keine neuen Kosten.", it: "La maggior parte dei negozi ne usa già uno — nessun costo aggiuntivo.", pt: "A maioria das lojas já usa um destes — sem custo novo.", nl: "De meeste winkels gebruiken er al een — geen nieuwe kosten.", pl: "Większość sklepów już z nich korzysta — bez nowych kosztów." },
  "No automated customer emails.": { es: "Sin correos automáticos a clientes.", fr: "Pas d'e-mails clients automatisés.", de: "Keine automatischen Kunden-E-Mails.", it: "Nessuna email automatica ai clienti.", pt: "Sem e-mails automáticos aos clientes.", nl: "Geen geautomatiseerde klant-e-mails.", pl: "Brak automatycznych e-maili do klientów." },
  "Email templates": { es: "Plantillas de correo", fr: "Modèles d'e-mail", de: "E-Mail-Vorlagen", it: "Modelli email", pt: "Modelos de e-mail", nl: "E-mailsjablonen", pl: "Szablony e-mail" },
