  "Served by a location": { es: "Atendido por una ubicación", fr: "Desservi par un site", de: "Von einem Standort bedient", it: "Servito da una sede", pt: "Servido por uma localização", nl: "Bediend door een locatie", pl: "Obsługiwane przez lokalizację" },
